#!/bin/bash
# Regenerates the PKCS#12 test files: identities made by OpenSSL the way
# other programs write them, with throwaway keys that exist only while the
# script runs. Every other PKCS#12 variant is generated by the tests.
#
# Needs OpenSSL 3 or later and python3, e.g. in a fedora:45 container:
#   docker run --rm -v "$PWD":/w:Z -w /w fedora:45 bash -c \
#     'dnf -y -q install openssl python3 && internal/certs/testdata/p12/gen.sh'
#
# Password of the protected files: Murmel-Test-ä1
set -euo pipefail
cd "$(dirname "$0")"
pw='Murmel-Test-ä1'
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

openssl req -x509 -newkey rsa:2048 -nodes -keyout "$tmp/key.pem" -out "$tmp/cert.pem" \
  -subj '/CN=Test OpenSSL' -days 7300 2>/dev/null
cat "$tmp/cert.pem" "$tmp/key.pem" >"$tmp/id.pem"

# OpenSSL 3 defaults: AES-256-CBC, PBKDF2-HMAC-SHA-256, SHA-256 MAC.
openssl pkcs12 -export -in "$tmp/id.pem" -passout "pass:$pw" -out openssl-default.p12
# OpenSSL 1.x defaults: RC2-40 certificates, 3DES key, SHA-1 MAC.
openssl pkcs12 -export -legacy -in "$tmp/id.pem" -passout "pass:$pw" -out openssl-legacy.p12
# Neither encryption nor MAC.
openssl pkcs12 -export -keypbe NONE -certpbe NONE -nomac -in "$tmp/id.pem" -passout pass: -out openssl-nomac.p12
# The official Mumble client's export: no encryption, MAC with an empty
# password, friendly name "Mumble Identity".
openssl pkcs12 -export -keypbe NONE -certpbe NONE -name 'Mumble Identity' -in "$tmp/id.pem" \
  -passout pass: -out mumble-format.p12

# The Mumble export in BER: the outer SEQUENCE with indefinite length.
# A file that states 2^31-1 MAC iterations (its MAC is no longer valid).
python3 -I - <<'EOF'
def length(n):
    if n < 0x80:
        return bytes([n])
    b = n.to_bytes((n.bit_length() + 7) // 8, "big")
    return bytes([0x80 | len(b)]) + b

def tlv(tag, body):
    return bytes([tag]) + length(len(body)) + body

def read(d, i):
    """Returns (tag, header end, value end) of the element at i."""
    tag, n = d[i], d[i + 1]
    i += 2
    if n & 0x80:
        k = n & 0x7F
        n = int.from_bytes(d[i:i + k], "big")
        i += k
    return tag, i, i + n

d = open("mumble-format.p12", "rb").read()
_, start, end = read(d, 0)
body = d[start:end]
open("mumble-format-ber.p12", "wb").write(b"\x30\x80" + body + b"\x00\x00")

# body = version, authSafe, macData; macData = DigestInfo, salt, iterations
_, _, v_end = read(body, 0)
_, _, a_end = read(body, v_end)
_, m_start, m_end = read(body, a_end)
mac = body[m_start:m_end]
_, _, di_end = read(mac, 0)
_, _, salt_end = read(mac, di_end)
mac = mac[:salt_end] + tlv(0x02, (2**31 - 1).to_bytes(4, "big"))
out = tlv(0x30, body[:a_end] + tlv(0x30, mac))
open("mumble-format-iterations.p12", "wb").write(out)
EOF
ls -l ./*.p12
